<style>
.or-head{margin-bottom:12px}.or-head h1{margin:0 0 2px;font-size:20px}.or-sub{margin:0;font-size:12.5px;color:var(--text-secondary);max-width:720px;line-height:1.45}
.or-banner{background:#fffbeb;border:1px solid #fcd34d;border-radius:10px;padding:8px 12px;margin-bottom:12px;font-size:12.5px;color:#78350f}
.or-grid{display:grid;grid-template-columns:360px minmax(0,1fr);gap:12px;align-items:start}@media (max-width:900px){.or-grid{grid-template-columns:1fr}}
.or-h3{margin:0 0 10px;font-size:14px;display:flex;gap:8px;align-items:center}
.or-form{display:grid;gap:12px;font-size:12.5px}.or-form label{display:grid;gap:4px;font-weight:600}.or-form label small{font-weight:400;color:var(--text-secondary)}
.or-form input[type=month],.or-form select,.or-form textarea{padding:6px 8px;font-size:13px;border:1px solid var(--border,#e5e7eb);border-radius:8px;background:#fff;font-family:inherit}
.or-form input[type=file]{font-size:12px}.or-form textarea{font-family:ui-monospace,Menlo,monospace;font-size:12px;line-height:1.4;min-height:220px}
.or-adv{font-size:12.5px}.or-adv>summary{cursor:pointer;font-weight:600;color:var(--text-secondary)}.or-adv[open]>summary{margin-bottom:6px}
.or-help{font-size:12px;color:var(--text-secondary);line-height:1.45;margin:0 0 8px}
.or-radios{display:grid;gap:4px}.or-radios label{display:flex;gap:8px;align-items:center;font-weight:400;padding:5px 8px;border:1px solid var(--border,#e5e7eb);border-radius:8px;cursor:pointer}.or-radios label:has(input:checked){border-color:#0f766e;background:#f0fdfa}
.or-table{width:100%;border-collapse:collapse;font-size:12.5px;line-height:1.35}.or-table th,.or-table td{padding:6px 8px;border-bottom:1px solid var(--border,#e5e7eb);text-align:left;vertical-align:top}.or-table th{font-size:11px;text-transform:uppercase;letter-spacing:.03em;color:var(--text-secondary);white-space:nowrap}.or-table .num{text-align:right;white-space:nowrap}
.or-muted{font-size:11.5px;color:var(--text-secondary)}.or-empty{color:var(--text-secondary);padding:14px!important}
.or-chip{display:inline-block;font-size:11px;padding:1px 8px;border-radius:999px;font-weight:600;white-space:nowrap}.or-chip--done{background:#dcfce7;color:#166534}.or-chip--run{background:#dbeafe;color:#1d4ed8}.or-chip--err{background:#fee2e2;color:#991b1b}.or-chip--draft{background:#f1f5f9;color:#475569}
.or-btn-sm{padding:4px 10px;font-size:12px}.or-link{font-size:12.5px}
.or-tiles{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:12px}@media (max-width:900px){.or-tiles{grid-template-columns:repeat(2,minmax(0,1fr))}}
.or-tile{background:#fff;border:1px solid var(--border,#e5e7eb);border-radius:10px;padding:10px 12px;display:grid;gap:3px}.or-tile span{font-size:11.5px;color:var(--text-secondary)}.or-tile b{font-size:19px;line-height:1.15}
.or-tile--main{background:#0f766e;border-color:#0f766e;color:#fff}.or-tile--main span{color:rgba(255,255,255,.85)}
.or-flags{margin:0;padding-left:18px;font-size:12.5px;line-height:1.5}.or-flags li{margin:3px 0}
.or-log{background:#0f172a;color:#e2e8f0;border-radius:10px;padding:10px 12px;font-size:11.5px;line-height:1.45;white-space:pre-wrap;max-height:420px;overflow:auto;font-family:ui-monospace,Menlo,monospace}
.or-progress{display:flex;gap:12px;align-items:center;font-size:13px}.or-spin{width:18px;height:18px;border:3px solid #cbd5e1;border-top-color:#0f766e;border-radius:50%;animation:or-spin 1s linear infinite}@keyframes or-spin{to{transform:rotate(360deg)}}
.or-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-top:12px}
.or-files{font-size:12.5px;line-height:1.6;color:var(--text-secondary)}.or-files b{color:inherit}
.or-err{background:#fee2e2;border:1px solid #fecaca;border-radius:10px;padding:8px 12px;font-size:12.5px;color:#991b1b;margin-bottom:12px}
</style>
